/* run cost */
.rcst{padding:0}
.rcs-top{display:flex;align-items:flex-start;justify-content:space-between;padding:16px}
.rcs-num{display:flex;align-items:baseline;gap:6px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:30px;letter-spacing:-.5px}
.rcs-of{font-size:13px;color:var(--muted)}
.rcs-bar{position:relative;height:6px;margin:0 16px 14px;background:var(--line)}
.rcs-bar i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .25s linear,background-color .3s}
.rcs-bar.hot i{background:var(--danger)}
.rcs-mark{position:absolute;left:90%;top:-4px;bottom:-4px;width:1px;background:var(--text-dim)}
.rcs-rows{border-top:1px solid var(--line);padding:6px 0}
.rcs-row{display:flex;justify-content:space-between;padding:7px 16px;font-size:13px;color:var(--text-dim)}
.rcs-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-top:1px solid var(--line)}
.rcs-foot .btn{padding:8px 14px;font-size:13px}

/* ---------- run cost ---------- */
{
  const used = $('#rcs-used'), fill = $('#rcs-fill'), bar = fill.parentElement, st = $('#rcs-state'), btnT = $('#rcs-run-t'), cap = $('#rcs-cap');
  const LIMIT = 2000; let v = 0, timer = null, mode = 'idle';
  function paint(){
    used.textContent = fmt(v); fill.style.width = (v / LIMIT * 100) + '%'; bar.classList.toggle('hot', v >= LIMIT * .9);
    $('#rcs-in').textContent = fmt(v * 38); $('#rcs-out').textContent = fmt(v * 5.2); $('#rcs-tools').textContent = fmt(Math.floor(v / 110));
  }
  function stop(){ clearInterval(timer); timer = null; }
  function run(){
    mode = 'run'; setPill(st, 'prog', 'Running'); swapText(btnT, 'Stop'); Sound.play('on');
    timer = setInterval(() => {
      v = Math.min(LIMIT, v + 9 + Math.random() * 16); paint();
      if (Math.random() < .25) ambient('c27', 'stream');
      if (cap.getAttribute('aria-checked') === 'true' && v >= LIMIT * .9 && mode === 'run'){ stop(); mode = 'capped'; setPill(st, 'warn', 'Paused at 90%'); swapText(btnT, 'Continue'); Sound.play('fail'); }
      if (v >= LIMIT){ stop(); mode = 'done'; setPill(st, 'fail', 'Budget reached'); swapText(btnT, 'Reset'); Sound.play('fail'); }
    }, 140);
  }
  $('#rcs-run').addEventListener('click', () => {
    if (mode === 'idle' || mode === 'stopped'){ run(); }
    else if (mode === 'run'){ stop(); mode = 'stopped'; setPill(st, 'todo', 'Stopped'); swapText(btnT, 'Resume'); Sound.play('off'); }
    else if (mode === 'capped'){ mode = 'over'; setPill(st, 'prog', 'Running over cap'); swapText(btnT, 'Stop'); run(); mode = 'over'; }
    else if (mode === 'over'){ stop(); mode = 'stopped'; setPill(st, 'todo', 'Stopped'); swapText(btnT, 'Resume'); }
    else { v = 0; paint(); mode = 'idle'; setPill(st, 'todo', 'Idle'); swapText(btnT, 'Start run'); Sound.play('tab'); }
  });
  cap.addEventListener('click', () => { const on = cap.getAttribute('aria-checked') !== 'true'; cap.setAttribute('aria-checked', on); Sound.play(on ? 'on' : 'off'); });
  paint();
}
